args.sparql:
SELECT DISTINCT ?spouse ?spouseLabel WHERE {
  VALUES ?p { dbo:spouse dbp:spouse }
  dbr:Coretta_Scott_King ?p ?spouse .
  OPTIONAL { ?spouse rdfs:label ?spouseLabel . FILTER(lang(?spouseLabel) = "en") }
}

SELECT DISTINCT ?birthPlace ?birthPlaceLabel WHERE {
