output.sparql:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT ?spouse ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Coretta_Scott_King ?spProp ?spouse .
  VALUES ?spProp {
    dbo:spouse dbp:spouse
  }
  ?spouse ?bpProp ?birthPlace .
  VALUES ?bpProp {
    dbo:birthPlace dbp:placeBirth dbp:birthPlace
  }
  OPTIONAL {
    ?birthPlace rdfs:label ?birthPlaceLabel .
    FILTER(lang(?birthPlaceLabel) = "en")
  }
}

